G=load(); print(sorted(G))
# Hypothesis: band maxcol M; fill rows whose lastnonzero == M, extending to edge
for name in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4','Demo pair 5']:
    gi,go=G[name+' input'],G[name+' output']
    from collections import Counter
    cnt=Counter(v for row in gi for v in row); bg=cnt.most_common(1)[0][0]
    band_rows=[]; cur=None
    for rr,row in enumerate(gi):
        if any(v!=bg for v in row):
            if cur is None: cur=rr
        else:
            if cur is not None: band_rows.append((cur,rr-1)); cur=None
    # collect bands simply: consecutive nonzero rows
    bands=[]; b=[]
    for rr in range(len(gi)):
        if any(v!=bg for v in gi[rr]): b.append(rr)
        else:
            if b: bands.append(b); b=[]
    if b: bands.append(b)
    ok=True
    for band in bands:
        Ms=max(c for r in band for c,v in enumerate(gi[r]) if v!=bg)
        filled=set()
        for r in band:
            lnz=max(c for c,v in enumerate(gi[r]) if v!=bg,default=-1)
            if go[r][W:=len(gi[r])] - 1 >= lnz and any(go[r][c]!=gi[r][c] for c in range(lnz+1,W)):
                filled.add(r)
        pred={r for r in band if max(c for c,v in enumerate(gi[r]) if v!=bg)==Ms}
        mism=sorted(filled^pred)
        ok = ok and not mism
        print(name,'band',band,'Ms',Ms,'filled',sorted(filled),'pred',sorted(pred),'mismatch' if mism else '')
    print(name,'OK' if ok else 'FAIL')

